// A60 · "Clean & Guard" Code node in "Feedback Save": one place that cleans every intake before it is stored.
// Keeps only what the desk needs (source, product, text, time). Phone numbers and emails inside the text are masked (DPDP: store the minimum).
const SOURCES = ['form', 'telegram', 'whatsapp'];
const PRODUCTS = [
  ['botbhai', ['bot bhai', 'whatsapp bot', 'chatbot']],
  ['jobcard', ['job card', 'invoice app']],
  ['kits', ['kit', 'gate', 'sheet']],
  ['tab-lifeboat', ['lifeboat', 'extension', 'tabs']],
  ['deals', ['deal', 'calculator', 'sip', 'emi']],
  ['ledger-peaks', ['ledger', 'finops', 'ai cost', 'dpdp']],
  ['trading-lab', ['trading', 'paper trade']],
  ['site', ['website', 'site', 'kalpa bhai']],
];
const pick = (s) => {
  const t = String(s || '').toLowerCase();
  for (const [id, words] of PRODUCTS) if (t.includes(id) || words.some((w) => t.includes(w))) return id;
  return '';
};
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const source = String(j.source || '').toLowerCase().trim();
  if (!SOURCES.includes(source)) continue;
  let text = String(j.text ?? '')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '')
    .replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[email]')
    .replace(/\+?\d[\d\s-]{8,}\d/g, '[number]')
    .replace(/\s+/g, ' ')
    .trim();
  if (Array.from(text).length < 3) continue;
  text = Array.from(text).slice(0, 1000).join('');
  const product = pick(j.product) || pick(text) || 'general';
  const d = new Date(j.created);
  const created = isNaN(d.getTime()) || d.getTime() > Date.now() + 864e5 ? new Date().toISOString() : d.toISOString();
  out.push({ json: { source, product, text, created } });
}
return out;
